CREATE OR REPLACE FUNCTION public.folha_salvar_vinculo(p_usuario uuid,p_unidade uuid,p_id uuid,p_dados jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE c public.folha_colaboradores; origem public.folha_colaboradores; BEGIN IF NOT public.folha_pode(p_usuario,p_unidade,'ver') OR NOT public.folha_pode(p_usuario,p_unidade,'colaboradores') THEN RAISE EXCEPTION 'Sem permissão nesta unidade'; END IF; IF (p_dados ? 'cpf' OR p_dados ? 'pix') AND NOT public.folha_pode(p_usuario,p_unidade,'dados_pessoais') THEN RAISE EXCEPTION 'Sem permissão explícita para CPF e PIX'; END IF; PERFORM set_config('folha.usuario',p_usuario::text,true); IF p_id IS NOT NULL THEN SELECT * INTO c FROM public.folha_colaboradores WHERE id=p_id AND unidade_id=p_unidade FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Vínculo fora da unidade'; END IF; ELSE c.id=gen_random_uuid(); c.unidade_id=p_unidade; c.ativo=true; c.base=0; c.passagem=0; c.lider=false; c.created_by=p_usuario; c.created_at=now(); c.updated_at=now(); END IF; IF p_dados ? 'pessoa_id' THEN SELECT * INTO origem FROM public.folha_colaboradores x WHERE x.pessoa_id=(p_dados->>'pessoa_id')::uuid AND public.folha_pode(p_usuario,x.unidade_id,'ver') AND public.folha_pode(p_usuario,x.unidade_id,'colaboradores') LIMIT 1; IF NOT FOUND THEN RAISE EXCEPTION 'Sem acesso à pessoa de origem'; END IF; END IF; c=jsonb_populate_record(c,p_dados-'id'-'created_by'-'created_at'-'updated_at'-'unidade_id'); c.unidade_id=p_unidade; IF c.tipo='SEM_CONTRATO' THEN c.ativo=false; END IF; IF p_id IS NULL THEN INSERT INTO public.folha_colaboradores SELECT c.*; ELSE UPDATE public.folha_colaboradores SET pessoa_id=c.pessoa_id,nome=c.nome,tipo=c.tipo,cpf=c.cpf,pix=c.pix,funcao=c.funcao,turno=c.turno,turno2=c.turno2,base=c.base,passagem=c.passagem,lider=c.lider,lider_valor=c.lider_valor,valor_fds=c.valor_fds,valor_feriado=c.valor_feriado,ativo=c.ativo WHERE id=p_id AND unidade_id=p_unidade; END IF; RETURN jsonb_build_object('ok',true,'id',c.id); END $$;
REVOKE ALL ON FUNCTION public.folha_salvar_vinculo(uuid,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.folha_salvar_vinculo(uuid,uuid,uuid,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.folha_hash_entrada(p_unidade uuid,p_comp text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT md5(COALESCE((SELECT string_agg(id::text||'@'||updated_at::text,',' ORDER BY id) FROM public.folha_colaboradores WHERE unidade_id=p_unidade),'')||'|'||COALESCE((SELECT string_agg(id::text||'@'||updated_at::text,',' ORDER BY id) FROM public.folha_lancamentos WHERE unidade_id=p_unidade AND competencia=p_comp),'')||'|'||COALESCE((SELECT updated_at::text FROM public.folha_config WHERE id=1),'')) $$;
CREATE OR REPLACE FUNCTION public.folha_identidade_permitida() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE u uuid; BEGIN u=COALESCE(auth.uid(),NULLIF(current_setting('folha.usuario',true),'')::uuid); IF TG_OP='INSERT' AND NEW.pessoa_id IS NOT NULL AND u IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.folha_colaboradores c WHERE c.pessoa_id=NEW.pessoa_id AND public.folha_pode(u,c.unidade_id,'ver') AND public.folha_pode(u,c.unidade_id,'colaboradores')) THEN RAISE EXCEPTION 'Sem acesso à identidade de origem'; END IF; IF TG_OP='UPDATE' AND NEW.pessoa_id IS DISTINCT FROM OLD.pessoa_id AND auth.uid() IS NOT NULL THEN RAISE EXCEPTION 'Associação de identidade exige operação autorizada'; END IF; RETURN NEW; END $$;
CREATE TRIGGER a_folha_identidade_permitida BEFORE INSERT OR UPDATE ON public.folha_colaboradores FOR EACH ROW EXECUTE FUNCTION public.folha_identidade_permitida();